const input = $input.first().json;
const event = input.event || input;
const context = input.context || {};
const order = context.order || {};
const customer = context.customer || {};
const tracking = context.tracking || {};

const actionKey = `delivery:${event.orderId || 'unknown'}:${event.eventType}`;

return [{
  json: {
    event,
    context,
    order,
    customer,
    tracking,
    orderValue: order.value || context.rawPayload?.orderValue || 0,
    isVip: (customer.previousOrders || 0) >= 5 || (customer.lifetimeValue || 0) > 500,
    actionKey
  }
}];

