const item = $input.first().json;
let text = item.text || item.output || JSON.stringify(item);
text = String(text).replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    severity: 'HIGH',
    decision: 'HUMAN_ESCALATION',
    reason: 'AI parse failed',
    confidence: 0.1,
    action: 'HUMAN_ESCALATION',
    channel: 'slack',
    message: '',
    escalate: true,
    priority: 'high'
  };
}

const upstream = $('Prepare Delivery Context').first().json;
const allowed = ['NO_ACTION','PROACTIVE_EMAIL','PROACTIVE_SMS','SUPPORT_ALERT','HUMAN_ESCALATION'];
if (!allowed.includes(parsed.decision)) {
  parsed.decision = 'HUMAN_ESCALATION';
  parsed.escalate = true;
}

return [{
  json: {
    agent: 'delivery_exception',
    decision: parsed.decision,
    reason: parsed.reason || '',
    confidence: Number(parsed.confidence) || 0,
    action: parsed.action || parsed.decision,
    channel: parsed.channel || 'email',
    message: parsed.message || '',
    escalate: !!parsed.escalate || ['HIGH','CRITICAL'].includes(parsed.severity),
    priority: parsed.priority || parsed.severity?.toLowerCase() || 'medium',
    severity: parsed.severity || 'WATCH',
    customerId: upstream.event?.customerId || '',
    orderId: upstream.event?.orderId || '',
    status: 'decided',
    actionKey: upstream.actionKey,
    customerEmail: upstream.customer?.email || null,
    customerName: upstream.customer?.name || 'Customer'
  }
}];

const d = $input.first().json;
return [{
  json: {
    ...d,
    status: d.escalate ? 'escalated' : 'action_executed'
  }
}];
